def _validated(ranges):
    """Return a new list of ranges after checking the ordering rule."""
    result = []
    for start, end in ranges:
        if start > end:
            raise ValueError("range start must not exceed range end")
        result.append((start, end))
    return result


def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges. See TASK.md."""
    ordered = sorted(_validated(ranges))
    if not ordered:
        return []

    merged = [ordered[0]]
    for start, end in ordered[1:]:
        previous_start, previous_end = merged[-1]
        if start <= previous_end + 1:
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return merged


def subtract(ranges, holes):
    """The integers in `ranges` that are not in `holes`, as merged ranges."""
    source = merge(ranges)
    excluded = merge(holes)
    result = []

    hole_index = 0
    for start, end in source:
        current = start
        while hole_index < len(excluded) and excluded[hole_index][1] < current:
            hole_index += 1

        index = hole_index
        while index < len(excluded) and excluded[index][0] <= end:
            hole_start, hole_end = excluded[index]
            if hole_start > current:
                result.append((current, min(end, hole_start - 1)))
            current = max(current, hole_end + 1)
            if current > end:
                break
            index += 1
        if current <= end:
            result.append((current, end))
    return result


def count(ranges):
    """How many distinct integers the ranges hold."""
    return sum(end - start + 1 for start, end in merge(ranges))
